# The gate this case exists for, asserted directly: every model now on the table
# — the no-man's-land block AND the one aimed too close — is more than 9" from
# every enemy, edge to edge. The clamp may only move a drop TO a legal spot; it
# can never carry one past the rule.
var dc = tree.current_scene.deployment_controller
var worst = 1000.0
for i in range(dc.temp_positions.size()):
	if dc.temp_positions[i] == null:
		continue
	for enemy in GameState.get_enemy_model_positions(2):
		var edge = dc.temp_positions[i].distance_to(Vector2(enemy.x, enemy.y)) / 40.0 - (32.0 / 2.0) / 25.4 - (float(enemy.base_mm) / 2.0) / 25.4
		if edge < worst:
			worst = edge
return snappedf(worst, 0.01)

